/// Contract: `VG.Spec.Sha3.squeezeContract`. Constant time: only the pointers, `rate`, `pos` and `outlen` may affect timing, not the state.
///
/// # Safety
///
/// * `state` must be valid for reads and writes of 200 bytes.
/// * `out` must be valid for reads and writes of `outlen` bytes.
/// * `rate` must be 72, 104, 136, 144 or 168, and `pos` at most `rate`.
/// * `state` and `out` must not overlap each other (distinct Rust objects never do).
/// * Neither `state` nor `out` may overlap the 720 bytes of stack below the stack pointer, or wrap around the end of the address space (no Rust object does).
#[unsafe(naked)]
pub unsafe extern "C" fn vg_keccak_squeeze(state: *mut [u64; 25], rate: usize, pos: usize, out: *mut u8, outlen: usize) -> usize {
    core::arch::naked_asm!(
        r".long 0xf821fd61,0x39010020,0x7c0802a6,0xf821ffd1,0xf8010020,0xfb480200,0xfb680208,0xfb880210
.long 0xfba80218,0xfbc80220,0xfbe80228,0x3b430000,0x3b680000,0x3b840000,0x3ba50000,0x3bc60000
.long 0x3be70000,0x283f0000
beq %cr0, 20f
22:
.long 0x7d3ce850,0x28290000
beq %cr0, 23f
b 24f
23:
.long 0x3ba00000,0x387a0000,0x389b0000
bl {vg_keccak_f1600}
24:
.long 0x39400007,0x7faa5038,0x397ffff8,0x796b0fe0,0x7d4a5b78,0x282a0000
beq %cr0, 25f
.long 0x7d5aea14,0x892a0000,0x993e0000,0x3bde0001,0x3bbd0001,0x3bffffff
b 26f
25:
.long 0x7d5aea14,0xe92a0000,0xf93e0000,0x3bde0008,0x3bbd0008,0x3bfffff8
26:
.long 0x283f0000
bne %cr0, 22b
b 21f
20:
21:
.long 0x387d0000,0xeb5b0200,0xeb9b0210,0xebbb0218,0xebdb0220,0xebfb0228,0xeb7b0208,0xe8010020
.long 0x38210030,0x7c0803a6,0x382102a0,0x4e800020",
        vg_keccak_f1600 = sym super::sha3::vg_keccak_f1600,
    )
}

